    line-height: 2;
    color: var(--c-muted);
  }

  .og-points li::before { content: '▸ '; color: var(--c-dim); }

  .og-foot {
    margin: auto 0 0;
    font-size: 13px;
    color: var(--c-dim);
    font-family: 'Cascadia Code', 'SF Mono', monospace;
  }

  /* The app bleeds off the right edge: a whole window shrunk to fit would be
